package com.ruoyi.web.controller.system;

import com.ruoyi.common.core.controller.BaseController;
import com.ruoyi.common.core.domain.AjaxResult;
import com.ruoyi.common.core.page.TableDataInfo;
import com.ruoyi.common.annotation.Log;
import com.ruoyi.common.enums.BusinessType;
import com.ruoyi.system.domain.SysUser;
import com.ruoyi.system.service.ISysUserService;
import org.springframework.security.access.prepost.PreAuthorize;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;
import java.util.List;

@RestController
@RequestMapping("/system/user")
public class SysUserController extends BaseController {

    private final ISysUserService userService;

    public SysUserController(ISysUserService userService) {
        this.userService = userService;
    }

    @PreAuthorize("@ss.hasPermi('system:user:list')")   // 权限字符串校验
    @GetMapping("/list")
    public TableDataInfo list(SysUser user) {
        startPage();                                      // PageHelper 分页开关
        List<SysUser> list = userService.selectUserList(user); // 紧随其后的查询自动分页
        return getDataTable(list);                        // {total, rows} 结构
    }
}

package com.ruoyi.framework.security.filter;

import java.io.IOException;
import com.ruoyi.common.core.domain.model.LoginUser;
import com.ruoyi.framework.web.service.TokenService;
import jakarta.servlet.FilterChain;
import jakarta.servlet.ServletException;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import org.springframework.security.core.context.SecurityContextHolder;
import org.springframework.stereotype.Component;
import org.springframework.web.filter.OncePerRequestFilter;

@Component
public class JwtAuthenticationTokenFilter extends OncePerRequestFilter {

    private final TokenService tokenService;

    public JwtAuthenticationTokenFilter(TokenService tokenService) {
        this.tokenService = tokenService;
    }

    @Override
    protected void doFilterInternal(HttpServletRequest request,
                                    HttpServletResponse response,
                                    FilterChain chain) throws ServletException, IOException {
        LoginUser loginUser = tokenService.getLoginUser(request);   // 1. 解析 Token → Redis 取登录人
        if (loginUser != null
            && SecurityContextHolder.getContext().getAuthentication() == null) {
            tokenService.verifyToken(loginUser);                    // 2. 滑动续期
            var authentication = tokenService.createLoginUserAuthentication(loginUser);
            SecurityContextHolder.getContext().setAuthentication(authentication); // 3. 放入上下文
        }
        chain.doFilter(request, response);                          // 4. 继续过滤链
    }
}
